// Package notesapi implements a small in-memory REST API for notes.
package notesapi

import (
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
	"sync"
)

// Note is a single note. Do not change this type.
type Note struct {
	ID    string `json:"id"`
	Title string `json:"title"`
	Body  string `json:"body"`
}

// Server serves the notes REST API. See spec.md for the required endpoints.
type Server struct {
	mu     sync.Mutex
	notes  []Note
	nextID int
}

// NewServer returns a new, empty Server. Do not change this signature.
func NewServer() *Server {
	return &Server{nextID: 1}
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	notesPath := r.URL.Path == "/notes"
	if notesPath {
		switch r.Method {
		case http.MethodPost:
			s.handleCreate(w, r)
			return
		case http.MethodGet:
			s.handleList(w)
			return
		}
	}

	// /notes/{id}
	if parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/"); len(parts) == 2 && parts[0] == "notes" {
		switch r.Method {
		case http.MethodGet:
			s.handleGet(w, parts[1])
			return
		case http.MethodDelete:
			s.handleDelete(w, parts[1])
			return
		}
	}

	w.WriteHeader(http.StatusNotFound)
}

func (s *Server) handleCreate(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Title string `json:"title"`
		Body  string `json:"body"`
	}
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		w.WriteHeader(http.StatusBadRequest)
		return
	}

	s.mu.Lock()
	note := Note{ID: strconv.Itoa(s.nextID), Title: in.Title, Body: in.Body}
	s.nextID++
	s.notes = append(s.notes, note)
	s.mu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(note)
}

func (s *Server) handleList(w http.ResponseWriter) {
	s.mu.Lock()
	notes := make([]Note, len(s.notes))
	copy(notes, s.notes)
	s.mu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(notes)
}

func (s *Server) handleGet(w http.ResponseWriter, id string) {
	s.mu.Lock()
	note, ok := s.find(id)
	s.mu.Unlock()
	if !ok {
		w.WriteHeader(http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(note)
}

func (s *Server) handleDelete(w http.ResponseWriter, id string) {
	s.mu.Lock()
	for i, n := range s.notes {
		if n.ID == id {
			s.notes = append(s.notes[:i], s.notes[i+1:]...)
			s.mu.Unlock()
			w.WriteHeader(http.StatusNoContent)
			return
		}
	}
	s.mu.Unlock()
	w.WriteHeader(http.StatusNotFound)
}

func (s *Server) find(id string) (Note, bool) {
	for _, n := range s.notes {
		if n.ID == id {
			return n, true
		}
	}
	return Note{}, false
}

package notesapi

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
)

func do(t *testing.T, s http.Handler, method, path string, body string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)
	return rec
}

func TestCreateListGetDelete(t *testing.T) {
	s := NewServer()

	rec := do(t, s, http.MethodPost, "/notes", `{"title":"t1","body":"b1"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("create: got %d, want %d", rec.Code, http.StatusCreated)
	}
	var n1 Note
	if err := json.NewDecoder(rec.Body).Decode(&n1); err != nil {
		t.Fatalf("decode created note: %v", err)
	}
	if n1.ID != "1" || n1.Title != "t1" || n1.Body != "b1" {
		t.Fatalf("unexpected created note: %+v", n1)
	}

	rec = do(t, s, http.MethodPost, "/notes", `{"title":"t2","body":"b2"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("create 2: got %d, want %d", rec.Code, http.StatusCreated)
	}
	var n2 Note
	json.NewDecoder(rec.Body).Decode(&n2)
	if n2.ID != "2" {
		t.Fatalf("expected second id 2, got %q", n2.ID)
	}

	rec = do(t, s, http.MethodGet, "/notes", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("list: got %d, want %d", rec.Code, http.StatusOK)
	}
	var list []Note
	if err := json.NewDecoder(rec.Body).Decode(&list); err != nil {
		t.Fatalf("decode list: %v", err)
	}
	if len(list) != 2 || list[0].ID != "1" || list[1].ID != "2" {
		t.Fatalf("unexpected list: %+v", list)
	}

	rec = do(t, s, http.MethodGet, "/notes/1", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("get: got %d, want %d", rec.Code, http.StatusOK)
	}
	var got Note
	json.NewDecoder(rec.Body).Decode(&got)
	if got != n1 {
		t.Fatalf("get: got %+v, want %+v", got, n1)
	}

	rec = do(t, s, http.MethodGet, "/notes/99", "")
	if rec.Code != http.StatusNotFound {
		t.Fatalf("get missing: got %d, want %d", rec.Code, http.StatusNotFound)
	}

	rec = do(t, s, http.MethodDelete, "/notes/1", "")
	if rec.Code != http.StatusNoContent {
		t.Fatalf("delete: got %d, want %d", rec.Code, http.StatusNoContent)
	}

	rec = do(t, s, http.MethodDelete, "/notes/1", "")
	if rec.Code != http.StatusNotFound {
		t.Fatalf("delete missing: got %d, want %d", rec.Code, http.StatusNotFound)
	}

	rec = do(t, s, http.MethodGet, "/notes", "")
	json.NewDecoder(rec.Body).Decode(&list)
	if len(list) != 1 || list[0].ID != "2" {
		t.Fatalf("list after delete: %+v", list)
	}
}

func TestCreateInvalidJSON(t *testing.T) {
	s := NewServer()
	rec := do(t, s, http.MethodPost, "/notes", `{"title":`)
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("invalid json: got %d, want %d", rec.Code, http.StatusBadRequest)
	}
}

func TestUnknownRoutes(t *testing.T) {
	s := NewServer()
	for _, tc := range []struct{ method, path string }{
		{http.MethodGet, "/"},
		{http.MethodPost, "/notes/1"},
		{http.MethodPut, "/notes"},
		{http.MethodDelete, "/notes"},
		{http.MethodGet, "/notes/1/2"},
		{http.MethodGet, "/other"},
	} {
		rec := do(t, s, tc.method, tc.path, "")
		if rec.Code != http.StatusNotFound {
			t.Errorf("%s %s: got %d, want %d", tc.method, tc.path, rec.Code, http.StatusNotFound)
		}
	}
}

func TestConcurrent(t *testing.T) {
	s := NewServer()
	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			body := fmt.Sprintf(`{"title":"t%d","body":"b%d"}`, i, i)
			rec := do(t, s, http.MethodPost, "/notes", body)
			if rec.Code != http.StatusCreated {
				t.Errorf("concurrent create %d: got %d", i, rec.Code)
				return
			}
			var n Note
			if err := json.NewDecoder(rec.Body).Decode(&n); err != nil {
				t.Errorf("decode: %v", err)
			}
			if _, err := io.Copy(io.Discard, nil); err != nil {
				t.Errorf("unused: %v", err)
			}
		}(i)
	}
	wg.Wait()

	rec := do(t, s, http.MethodGet, "/notes", "")
	var list []Note
	json.NewDecoder(rec.Body).Decode(&list)
	if len(list) != 50 {
		t.Fatalf("expected 50 notes, got %d", len(list))
	}
	seen := make(map[string]bool)
	for _, n := range list {
		if seen[n.ID] {
			t.Fatalf("duplicate id %q", n.ID)
		}
		seen[n.ID] = true
	}
}

var _ = bytes.NewReader

